const ovSelf=(id,base,inner,center)=>`<div style="position:relative">${R.byId[id].render(base,{})}<div class="scrim pt-fixed${center?' center':''}" style="${center&&!MO()?'align-items:center':''}">${inner}</div></div>`;
const tabBar=(items,on,o={})=>`<div class="tabs" style="${o.style||''}">${items.map(([k,l,go,badge])=>`<span class="tab${k===on?' on':''}"${go?` data-go="${go}"`:''}>${l}${badge!=null?` <span style="display:inline-flex;min-width:20px;height:20px;border-radius:10px;padding:0 6px;align-items:center;justify-content:center;font-size:12px;background:${k===on?'var(--blue)':'#5d6067'};color:#fff;margin-left:4px">${badge}</span>`:''}</span>`).join('')}</div>`;

