const MBC=[['Cashback',2,'USDT'],['Cashback',3,'USDT'],['Streak',3,'Days'],['Cashback',5,'USDT'],['Streak',4,'Days'],['Cashback',4,'USDT'],['Streak',7,'Days'],['Cashback',5,'USDT'],['Cashback',8,'USDT']];
const PHASE={join:'pre',noEligible:'pre',reselect:'pre',reselNone:'pre',failToast:'pre',confirm:'pre',preopen:'open',preopenNo:'open',
 normal:'run',today:'run',complete:'done',final:'done',tally:'end',result:'end',excluded:'end',payout:'end'};
const mbAlertTop=(tone,t,b)=>`<div style="background:${tone==='err'?'#fdd':'#ffe0b2'};border-radius:8px;padding:10px 16px;margin-top:24px"><div class="b2 semi" style="color:${tone==='err'?'#c62828':'#663c00'}">${t}</div><div class="cap" style="color:${tone==='err'?'#c62828':'#663c00'}">${b}</div></div>`;
function mbTabs(){return `<div data-mb-tabs style="background:#fff;border-bottom:1px solid var(--divider);position:sticky;top:var(--pt-bar-h,0px);z-index:20">${wrap(tabBar([['o','Overview'],['b','Bingo Missions'],['r','Rewards & Ranking'],['n','Notes']],'o',{style:'border-bottom:0'}).replace(/<span class="tab([^"]*)">(Overview|Bingo Missions|Rewards &amp; Ranking|Rewards & Ranking|Notes)/g,(m,c,l)=>`<span class="tab${c}" data-mb-tab="${{'Overview':'o','Bingo Missions':'b','Notes':'n'}[l]||'r'}">${l}`))}</div>`}
function mbTimer(){const box=v=>`<span style="display:inline-flex;align-items:center;justify-content:center;min-width:${MO()?48:60}px;height:${MO()?36:42}px;padding:0 6px;background:#fff;border-radius:8px;box-shadow:inset 0 1px 2px rgba(0,0,0,.25);font-size:${MO()?20:24}px;font-weight:700">${v}</span>`;const c=`<span class="h6 c2" style="font-weight:700">:</span>`;
 return `<div class="col g8"><span class="b2 semi c2">${T('Ends in','마감까지')}</span><div class="row g8">${box('9D')}${c}${box('23H')}${c}${box('59m')}${c}${box('21s')}</div></div>`}
function mbHero(st){
 const ph=PHASE[st];const mo=MO();
 const big=(n,u)=>`<div class="row" style="gap:8px;align-items:baseline;color:var(--blue)"><span style="font-size:${mo?56:80}px;font-weight:900;line-height:1.2;letter-spacing:-.5px">${n}</span><span style="font-size:${mo?28:40}px;font-weight:700">${u}</span></div>`;
 const pool=`<div class="col" style="gap:0"><span class="b1 bold cb">Total Ranking Pool</span>${big('5,000','USDT')}</div><div class="row g8"><span class="b1 c2">Maximum Bingo Rewards</span><span class="h6" style="font-weight:700">43 USDT</span></div>`;
 const stat=(ph==='run'||ph==='done')?`<div class="col" style="gap:0"><span class="b1 bold cb">Maximum Bingo Rewards</span>${big('43','USDT')}</div>`:pool;
 const dateBlock=(lbl,v,sub)=>`<div class="col g8"><span class="b2 semi c2">${lbl}</span><div class="row g8" style="align-items:baseline"><span style="font-size:${mo?26:34}px;font-weight:700">${v}</span>${sub?`<span class="b1 c2">${sub}</span>`:''}</div></div>`;
 const pill=(label,o={})=>`<button class="btn contained primary${o.dis?' ':''}" ${o.dis?'disabled':''} ${o.go?`data-go="${o.go}"`:''} style="border-radius:999px;height:50px;width:${mo?'100%':'280px'};font-size:16px;font-weight:600">${label}</button>`;
 let when='',cta='',cap='';
 if(ph==='open'){when=dateBlock('Opens','10.03','Opens at 09:00');cta=pill('Opens on Oct 3, 09:00',{dis:1})}
 else if(st==='tally'){when=dateBlock('Results','10.28, 09:00');cta=pill('Calculating',{dis:1})}
 else if(st==='result'){when=dateBlock('Reward Distribution','10.31, From 09:00');cta=pill('Participation Ended',{dis:1})}
 else if(st==='excluded'){when=dateBlock('Reward Distribution','10.31, From 09:00')}
 else if(st==='payout'){when=dateBlock('Reward Distribution','10.31','Paying Out Sequentially');cta=pill(T('Check Event Rewards','이벤트 리워드 확인하기'),{go:'summary.main'})}
 else{when=mbTimer();
  if(st==='join'||st==='failToast'){cta=pill('Join NOW',{go:'maxboard.main:pick'});cap=`<span class="b2 c2">You can participate until Oct 24, 08:59.</span>`}
  if(st==='noEligible'||st==='reselNone')cta=pill(T('Link Account','계정 연동하기'),{go:'link.addr:empty'});
  if(st==='reselect'||st==='confirm')cta=pill(T('Select New Account','새 계정 선택하기'),{go:'maxboard.main:repick'});}
 const sched={open:`Opens <b>Oct 3, 09:00</b>`,tally:`Results on <b>Oct 28, 09:00</b>`,result:`Rewards paid from <b>Oct 31, 09:00</b>`,excluded:`Rewards paid from <b>Oct 31, 09:00</b>`,payout:`Paying rewards since <b>Oct 31, 09:00</b>`}[ph==='open'?'open':st]
  ||(st==='today'?T('Ends Today','오늘 마감'):T(`Ends in <b>D-10</b> Oct 24, 08:59`,`<b>D-10</b> 10월 24일 08:59 마감`));
 const lost=mbAlertTop('err',T('You Can No Longer Participate with This wallet','참여 중이던 지갑으로 더 이상 참여할 수 없어요'),T('This wallet can no longer join this board.','이 지갑으로는 이 빙고판에 다시 참여할 수 없어요.'));
 const top=st==='reselect'||st==='confirm'?lost
  :st==='reselNone'?lost+`<div style="margin-top:-16px">${mbAlertTop('warn',T('No Eligible EdgeX wallet','참여할 수 있는 EdgeX 지갑이 없어요'),T('Link a new wallet to participate again.','새 지갑을 연동하면 다시 참여할 수 있어요.'))}</div>`:'';
 const left=`<div class="col" style="gap:32px;position:relative;z-index:1"><div class="col g16"><div style="font-size:${mo?32:48}px;line-height:1.167">October EdgeX MAX BOARD</div><div style="font-size:${mo?16:20}px;line-height:1.6">Fill your bingo with cashback and earn USDT rewards</div></div><div class="col g8">${stat}</div><div class="col g24">${when}${cta||cap?`<div class="col g16">${cta}${cap}</div>`:''}</div></div>`;
 const art=mo?`<img src="${A('rw-mb-hero.webp')}" style="width:220px;margin:0 auto" alt="">`:`<div style="position:absolute;right:74px;top:4px;width:505px;height:502px;pointer-events:none"><img src="${A('rw-mb-glow.svg')}" style="position:absolute;left:-194px;top:-201px;width:905px;max-width:none;opacity:.9" alt=""><img src="${A('rw-mb-hero.webp')}" style="position:relative;width:505px;height:502px" alt=""></div>`;
 return `<section style="background:#e9f0ff;padding:${mo?'0 0 24px':'0 0 40px'}">${wrap(`${top}<div class="${mo?'col':'row between'}" style="padding:${mo?'16px 0':'40px 0'};${mo?'align-items:flex-start;gap:16px':''}"><button class="btn text black md" data-go="benefits.list" style="color:#5d6067;font-weight:700;padding:8px 11px"><img src="${A('rw-ic-back.svg')}" class="ic" alt="">All benefits</button><div class="row g16"><img src="${A('logo.svg')}" style="width:124px" alt="TetherMax"><span style="width:1px;height:18px;background:var(--divider)"></span><span class="row g12">${C.dex('EdgeX',22)}<span class="b1 bold">EdgeX</span></span></div></div>
 <div style="position:relative;${mo?'':'min-height:510px'}">${mo?art:''}${left}${mo?'':art}</div>
 <div class="${mo?'col center':'row between'}" style="background:#fff;border-radius:16px;padding:12px 24px;margin-top:${mo?24:40}px;${mo?'align-items:center':''}"><div class="${mo?'col g4 center':'row g16'}" style="${mo?'align-items:center':''}"><span class="row g8"><img src="${A('rw-ic-calendar.svg')}" style="width:18px" alt=""><span class="b1 semi">Event schedule</span></span><span class="b1 c2">${sched}</span></div><button class="btn text black md" style="color:#5d6067;font-weight:700" data-mb-sched aria-expanded="false">View schedule${ic('arrow-drop-down')}</button></div>${mbSchedule(st)}`)}</section>`}
// 전체 일정(기본 접힘) — PC 가로 단계 · 모바일 세로 타임라인, 현재 단계 강조
function mbSchedule(st){const ph=PHASE[st]||'run',mo=MO();
 const steps=[['open','Opens <b>Oct 3, 09:00</b>'],['run','You can participate until <b>Oct 24, 08:59</b>.'],['tally','Results on <b>Oct 28, 09:00</b>'],['pay','Rewards paid from <b>Oct 31, 09:00</b>']];
 const cur={pre:'run',open:'open',run:'run',done:'run',end:st==='tally'?'tally':'pay'}[ph]||'run';
 return `<div data-mb-sched-body hidden style="background:#fff;border-radius:16px;padding:16px 24px;margin-top:8px"><div class="${mo?'col':'row'}" style="gap:${mo?12:16}px">${steps.map(([k,t],i)=>`<div class="${mo?'row':'col'}" style="flex:1;gap:8px;align-items:${mo?'center':'flex-start'}"><span style="width:24px;height:24px;border-radius:12px;flex:none;display:inline-flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;background:${k===cur?'var(--blue)':'#e6e9ef'};color:${k===cur?'#fff':'#5d6067'}">${i+1}</span><span class="b2${k===cur?' semi':' c2'}">${t}</span></div>`).join('')}</div></div>`}

function mbCell(i,state){const [lbl,n,u]=MBC[i];
 const st={done:'background:rgba(36,83,240,.85);color:rgba(255,255,255,.55)',can:'background:#fff;color:var(--blue)',canS:'background:#d9f5f3;color:#005f5a'}[state]||'background:rgba(0,0,0,.08);box-shadow:inset 0 2px 3px rgba(0,0,0,.25);color:rgba(255,255,255,.7)';
 return `<div style="position:relative;height:${MO()?64:80}px;border-radius:16px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;${st}"><span class="b2">${lbl}</span><span class="row g4" style="align-items:baseline"><b style="font-size:20px">${n}</b><span class="b2">${u}</span></span>${state==='done'?`<span style="position:absolute;right:10px;top:8px;width:16px;height:16px;border-radius:50%;background:#fff;color:var(--blue);font-size:11px;display:flex;align-items:center;justify-content:center;font-weight:700">✓</span>`:''}</div>`}
function mbCoin(v,on){return `<div style="position:relative;width:${MO()?52:64}px;height:${MO()?52:64}px;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:4px 0 10px;flex:none"><img src="${A('rw-mb-coin.png')}" style="position:absolute;inset:0;width:100%;height:100%" alt=""><b style="position:relative;font-size:${MO()?16:20}px;line-height:1.6;margin-bottom:-6px;color:rgba(0,0,0,.87)">${v}</b><span style="position:relative;font-size:12px;color:rgba(0,0,0,.6)">USDT</span>${on?`<span style="position:absolute;right:-2px;top:-2px;width:20px;height:20px;border-radius:50%;background:#2e7d32;color:#fff;font-size:12px;display:flex;align-items:center;justify-content:center">✓</span>`:''}</div>`}
function mbBoard(st){
 const ph=PHASE[st];const all=ph==='done';
 const map={};let done=[],can=[],canS=[];
 if(ph==='run'){done=[0,2];can=[1,3,5,7,8];canS=[4]}
 if(ph==='end')done=st==='payout'?[0,1,2,4,7]:[0,2];
 if(all)done=[0,1,2,3,4,5,6,7,8];
 done.forEach(i=>map[i]='done');can.forEach(i=>map[i]='can');canS.forEach(i=>map[i]='canS');
 const rowOn=r=>all||(st==='payout'&&r===0),colOn=c=>all||(st==='payout'&&c===1);
 const rows=[0,1,2].map(r=>`<div class="row" style="gap:16px"><div style="flex:1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px">${[0,1,2].map(c=>mbCell(r*3+c,map[r*3+c])).join('')}</div>${mbCoin(['+3','+3','+5'][r],rowOn(r))}</div>`).join('');
 const cols=`<div class="row" style="gap:16px"><div style="flex:1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;justify-items:center">${[0,1,2].map(c=>mbCoin(['+3','+3','+5'][c],colOn(c))).join('')}</div><span style="width:${MO()?52:64}px"></span></div>`;
 const bullets=ph==='pre'||ph==='open'||ph==='run'?[T('After you join, use your cashback to check any cell you choose.','참여하면 받은 캐시백으로 원하는 칸을 골라 체크할 수 있어요.'),'Choose any cell to check. Checked cells cannot be undone.']:all?['Choose any cell to check. Checked cells cannot be undone.']:[];
 const cnt=ph==='end'||ph==='run'?done.length:all?9:0;
 return `<div style="position:relative;background:rgba(0,49,198,.7);border-radius:32px;padding:${MO()?'24px 16px':'32px'};overflow:hidden;display:flex;flex-direction:column;gap:24px;background-image:radial-gradient(circle at 80% 0%,rgba(17,118,240,.55),transparent 55%),radial-gradient(circle at 10% 100%,rgba(17,118,240,.45),transparent 60%)">
  <div class="col g12"><div class="h6 center" style="color:#fff;font-weight:700">My Bingo Board</div>${bullets.length?`<div class="col g4">${bullets.map(b=>`<div class="row g8 b2" style="color:#fff"><span style="width:4px;height:4px;border-radius:50%;background:#fff;flex:none"></span>${b}</div>`).join('')}</div>`:''}</div>
  <div class="col g16"><div class="row g4"><b class="b1" style="color:#fff;font-weight:700">${cnt}</b><span class="b2" style="color:rgba(255,255,255,.7)">/ 9 checked</span></div>${rows}${cols}</div>
  <hr style="border:0;border-top:1px solid rgba(255,255,255,.3);margin:0;width:100%">
  <div class="row between" style="color:#fff"><span class="b2 semi">${all?'✓ Full Board Complete':'Full Board Reward for All 9 Cells'}</span><span class="row g4" style="align-items:baseline"><b style="font-size:24px">+21</b><span class="b2 bold">USDT</span></span></div></div>`}
function mbGauge(st){
 const ph=PHASE[st];const end=ph==='end';const done=ph==='done';
 const chip=(t,tone)=>`<span style="display:inline-flex;align-items:center;justify-content:center;text-align:center;padding:4px 10px;border-radius:999px;font-size:${end?12:13}px;line-height:1.3;font-weight:600;${tone==='blue'?'background:#c5d4ff;color:var(--blue)':tone==='teal'?'background:#d9f5f3;color:#005f5a':'background:rgba(255,255,255,.2);color:#fff'}">${t}</span>`;
 const closed=chip('Checking closed after<br>participation ended','grey');
 const gauge=st==='payout'?'4.40':done?'5.90':'12.40';const streak=done?'8':'4';
 const bar=(ph==='run'||done)?`<div style="position:relative;height:28px;margin-top:8px"><div style="position:absolute;left:0;right:0;top:6px;height:6px;border-radius:3px;background:rgba(255,255,255,.85)"></div><div style="position:absolute;left:0;width:${done?100:61}%;top:6px;height:6px;border-radius:3px;background:#0097a7"></div>${[['3 Days',47],['4 Days',61],['7 Days',100]].map(([l,p])=>`<span style="position:absolute;left:${p}%;transform:translateX(-${p===100?100:50}%);top:${(done||p<100)?-2:14}px;display:flex;flex-direction:column;align-items:center">${done||p<100?`<span style="width:22px;height:22px;border-radius:50%;background:#0097a7;color:#fff;font-size:12px;display:flex;align-items:center;justify-content:center;border:2px solid #fff">✓</span>`:''}<span class="cap" style="color:${done||p<100?'#fff':'rgba(255,255,255,.5)'};white-space:nowrap;margin-top:4px">${l}</span></span>`).join('')}</div><div style="height:16px"></div>`:'';
 const card=(t,d,lbl,val,unit,ch,extra)=>`<div style="background:#3a3f4a;border-radius:16px;padding:24px;color:#fff"><div class="row between"><span class="b1 semi">${t}</span><span style="width:24px;height:24px;border-radius:50%;background:#fff;color:#3a3f4a;font-weight:700;display:flex;align-items:center;justify-content:center">?</span></div><div class="b2" style="color:rgba(255,255,255,.7);margin-top:4px">${d}</div><hr style="border:0;border-top:1px dashed rgba(255,255,255,.35);margin:20px 0"><div class="b1" style="color:rgba(255,255,255,.7)">${lbl}</div><div class="row between" style="margin-top:4px;gap:8px"><span class="row g8" style="align-items:baseline"><b style="font-size:24px">${val}</b><span class="b2 semi">${unit}</span></span>${ch}</div>${extra||''}</div>`;
 return `<div class="col g16"><div><div style="font-size:${MO()?22:28}px;font-weight:700;color:#fff;line-height:1.334">How to Check Your Bingo Cells</div><div class="b1" style="color:rgba(255,255,255,.7);margin-top:8px">Cashback cells and Streak cells have different requirements.</div></div>
  ${card('Use Your Gauge for Cashback Cells','The USDT amount shown on a cell is deducted from your gauge.','Available Bingo Gauge',gauge,'USDT',end?closed:done?chip('Max Cells to Check 0 cells','grey'):chip('Max Cells to Check 5 cells','blue'))}
  ${card('Reach a Streak to Check Streak Cells','Streak cells do not use your gauge.','Current Cashback Streak',`${streak} Days`,'Cashback Streak',end?closed:done?chip('Max Cells to Check 0 cell','grey'):chip('Max Cells to Check 1 cell','teal'),bar)}</div>`}
function mbNotice(tone,t,b){const bg={blue:'rgba(0,123,255,.3)',brown:'rgba(237,108,2,.35)',navy:'rgba(0,123,255,.3)'}[tone];return `<div style="background:${bg};border-radius:8px;padding:12px 16px"><div class="b2 semi" style="color:#fff">${t}</div><div class="cap" style="color:rgba(255,255,255,.7)">${b}</div></div>`}
function mbSection2(st){
 const ph=PHASE[st];const mo=MO();
 const howto=`<div class="col" style="gap:40px"><div class="col g24"><span style="align-self:flex-start;background:#f2f2f5;border-radius:999px;padding:6px 12px;color:var(--blue);font-weight:700;font-size:14px">HOW TO PLAY</span><div style="font-size:${mo?22:28}px;font-weight:700;color:#fff">Turn your Cashback into rewards</div></div><div class="col g24">${[['01','Join MAX BOARD'],['02','Check bingo cells with Cashback'],['03','Complete bingo and earn rewards']].map(([n,t])=>`<div class="row g16" style="font-size:${mo?18:24}px;line-height:1.6"><b style="color:#2453f0;width:32px">${n}</b><span style="color:#fff">${t}</span></div>`).join('')}</div>`;
 let notice='';
 if(st==='join'||st==='failToast')notice=mbNotice('blue',T('You Have an Eligible wallet','참여할 수 있는 지갑이 있어요'),'Join now and the cashback you have received since Oct 3, 09:00 is added to your Bingo Gauge right away.');
 if(st==='preopen')notice=mbNotice('blue',T('You Have an Eligible wallet','참여할 수 있는 지갑이 있어요'),'You can participate from Oct 3, 09:00. Cashback you receive during the event is added to your Bingo Gauge automatically.');
 if(st==='preopenNo'||st==='noEligible')notice=mbNotice('brown',T('No Eligible EdgeX wallet','참여할 수 있는 EdgeX 지갑이 없어요'),T('Only EdgeX wallets registered on TetherMax on or after Sep 3, 09:00 can participate. Link a new EdgeX wallet to join.','9월 3일 09:00 이후 테더맥스에 등록된 EdgeX 지갑만 참여할 수 있어요. EdgeX 지갑을 새로 연동하면 참여할 수 있어요.'));
 if(st==='tally')notice=mbNotice('brown','Calculating','The participation period has ended. Results will be announced on Oct 28, 09:00.');
 const pay=T('Event rewards will be paid to your participating wallet from Oct 31, 09:00.','10월 31일 09:00부터 참여 지갑으로 이벤트 리워드가 지급돼요.');
 if(st==='result'||st==='excluded')notice=mbNotice('navy','Rewards Confirmed',pay);
 if(st==='payout')notice=mbNotice('navy','Paying Rewards',pay);
 const leftCol=(ph==='pre'||ph==='open')?howto+notice+'</div>':`<div class="col g16">${mbGauge(st)}${notice}</div>`;
 const info=t=>`<div class="row g8 b2" style="color:rgba(255,255,255,.85)"><span style="width:16px;height:16px;border:1.5px solid currentColor;border-radius:50%;font-size:10px;display:inline-flex;align-items:center;justify-content:center;flex:none">i</span>${t}</div>`;
 let below='';
 const nb=(a,b)=>`<div class="grid2" style="gap:16px">${[['Next Bingo',a],['Full Board',b]].map(([l,v])=>`<div class="row between" style="background:#1f45d6;border-radius:12px;padding:14px 20px;color:#fff"><span class="b2 semi">${l}</span><span class="b2 semi">${v}</span></div>`).join('')}</div>`;
 if(ph==='run')below=nb('1 cell','7 cell')+info(T('Updated once a day','하루 한 번 업데이트돼요'));
 if(st==='complete')below=nb('-','0 cell')+info(T('Rankings are updated daily.','랭킹은 매일 업데이트돼요'))+C.note('완성 직후(랭킹 ON): 국문 = 정책 문구(REQ-654), 영문 = 문구표_DEX');
 if(st==='final')below=nb('-','0 cell')+info(T('Final rankings will be shown when results are announced · Oct 28, 09:00','최종 순위는 결과 발표 때 확인할 수 있어요 · 10월 28일 09:00'));
 if(ph==='end')below=info('The participation period has ended, so cells can no longer be checked.');
 const coin3d=mo?'':`<div style="position:absolute;right:-33px;top:-48px;width:160px;height:158px;overflow:hidden;pointer-events:none"><img src="${A('rw-mb-coin3d.png')}" style="position:absolute;left:-121px;top:-122px;width:444px;max-width:none" alt=""></div>`;
 return `<section style="background:#121721;padding:${mo?'48px 0':'100px 0'}">${wrap(`<div class="col g16" style="margin-bottom:${mo?40:80}px"><span class="b1 bold" style="color:#fff">01 / BINGO MISSION</span><div class="row between wrap" style="gap:8px"><span style="font-size:${mo?24:34}px;font-weight:700;color:#fff;line-height:1.235">Earn Cashback. Complete your bingo.</span><span class="b1" style="color:rgba(255,255,255,.7)">Rewards for each completed row or column</span></div></div>
  <div style="display:grid;grid-template-columns:${mo?'1fr':'repeat(2,minmax(0,1fr))'};gap:40px;align-items:start"><div class="col" style="gap:40px">${leftCol}</div><div style="position:relative" class="col g16">${mbBoard(st)}${below}${coin3d}</div></div>`)}</section>`}
function mbMyRewards(st){
 const ph=PHASE[st];
 const head=`<div class="col g8"><span class="b2 bold cb">02 / REWARDS</span><div style="font-size:${MO()?20:24}px;font-weight:700;line-height:1.334">Your completed bingo.<br>Your rewards.</div></div>`;
 let right='';
 const lab=`<div class="cap c2">My Rewards</div>`;
 if(ph==='run')right=`${lab}<div class="b2 c2">Complete any row or column to receive a Bingo Reward. Check all 9 cells to also receive the Full Board Reward.</div>`;
 if(st==='tally'||st==='result'||st==='excluded')right=`${lab}<div class="b2 c2">You have no rewards because you did not complete a bingo.</div>`;
 const list=(rows,badge,tone)=>`<div class="row between">${lab}${C.badge(badge,tone)}</div>${rows.map(([k,v])=>`<div class="row between cap c2"><span>${k}</span><span>${v}</span></div>`).join('')}<hr class="divider" style="margin:8px 0"><div class="row between"><b class="b2">Total</b><b class="h6" style="font-weight:700">${rows.total}</b></div><div class="cap c3">${T('Event rewards will be paid to your participating wallet from Oct 31, 09:00.','10월 31일 09:00부터 참여 지갑으로 이벤트 리워드가 지급돼요.')}</div>`;
 if(st==='payout'){const r=[['Row 1 Bingo','3.00 USDT'],['Column 2 Bingo','3.00 USDT']];r.total='6.00 USDT';right=list(r,'Confirmed','green')}
 if(ph==='done'){const r=[['Row 1 Bingo','3.00 USDT'],['Row 2 Bingo','3.00 USDT'],['Row 3 Bingo','5.00 USDT'],['Column 1 Bingo','3.00 USDT'],['Column 2 Bingo','3.00 USDT'],['Column 3 Bingo','5.00 USDT'],['Full Board Reward','21.00 USDT']];r.total='43.00 USDT';right=list(r,'Pending','orange')}
 return `<div style="background:#fff;border-radius:24px;padding:${MO()?'24px':'32px 40px'};display:grid;grid-template-columns:${MO()||!right?'1fr':'1fr 1fr'};gap:24px">${head}${right?`<div class="col g4">${right}</div>`:''}</div>`}
function mbRanking(st){
 const ph=PHASE[st];const mo=MO();
 const title=`<div class="row g24" style="flex-wrap:wrap"><span style="font-size:24px;font-weight:700">Ranking Reward</span><span class="chip sm" style="border-radius:4px">Full Board Only</span></div><div class="b1 c2">Among traders who complete the Full Board, Ranking Rewards go to those with the most total cashback during the event.</div>`;
 const pool=`<div class="${mo?'col center':'row between'}" style="border-radius:24px;padding:24px ${mo?16:40}px;background:linear-gradient(90deg,#0031c6,#2453f0);color:#fff;${mo?'align-items:center;gap:12px':''}"><div class="col g4" style="${mo?'align-items:center':''}"><span class="b2">Total Ranking Rewards</span><span class="row g4" style="align-items:baseline"><b style="font-size:${mo?26:34}px">5,000</b><b class="b1">USDT</b></span></div><span class="row g8 b2 semi" style="${mo?'border:1px solid rgba(255,255,255,.6);border-radius:4px;padding:4px 10px':''}">View by Place ${mo?'':ic('arrow-forward','ic20')}</span></div>`;
 if(ph==='open')return `<div class="col g16">${title}${pool}<div style="background:#dbe7ff;border-radius:8px;padding:10px 16px" class="b2 semi cb">Rankings Open When the Event Starts</div></div>`;
 const pod=(t,id,place,cb,rw,raise)=>`<div style="background:#fff;border:.5px solid var(--divider);border-radius:24px;padding:24px;box-shadow:0 1px 10px rgba(2,133,254,.2),0 1px 1px rgba(0,0,0,.1);${raise&&!mo?'':'margin-top:24px'}" class="col g16"><div class="row between"><span class="row g8"><img src="${A(t)}" style="width:40px;height:40px" alt=""><b style="font-size:20px">${id}</b></span><span class="chip sm" style="background:var(--bg-accent)">${place}</span></div><div class="col g8"><div class="row between b2"><span class="c2">Total Cashback</span><span class="med">${cb}</span></div><div class="row between b2"><span class="c2">Ranking Reward</span><span class="semi cb">${rw}</span></div></div></div>`;
 const showDaily=ph!=='end';
 const podium=`${showDaily?`<div class="b1 semi c2">${st==='complete'?T('Updated once a day','랭킹은 매일 업데이트돼요'):T('Updated once a day','하루 한 번 업데이트돼요')}</div>`:C.note('집계 단계부터 <code>Updated once a day</code> 숨김(정책 D-1-4). Figma는 보임 — 정책 우선')}<div style="display:grid;grid-template-columns:${mo?'1fr':'repeat(3,minmax(0,1fr))'};gap:16px;align-items:start">${mo?pod('rw-trophy-1.png','48****57','1st','2,480.31 USDT','1,000 USDT',1)+pod('rw-trophy-2.png','30****62','2nd','1,902.55 USDT','600 USDT')+pod('rw-trophy-3.png','77****31','3rd','1,902.50 USDT','400 USDT'):pod('rw-trophy-2.png','30****62','2nd','1,902.55 USDT','600 USDT')+pod('rw-trophy-1.png','48****57','1st','2,480.31 USDT','1,000 USDT',1)+pod('rw-trophy-3.png','77****31','3rd','1,902.50 USDT','400 USDT')}</div>`;
 let me='';
 if(ph==='run')me='Complete the Full Board to enter the ranking.';
 if(st==='tally'||st==='result'||st==='payout')me='You did not complete the Full Board, so you are not ranked.';
 const meRow=ph==='done'?`<div style="display:grid;grid-template-columns:${mo?'48px 1fr 1fr 60px':'120px 1fr 240px 200px'};background:#cfe0ff;border-radius:8px;padding:14px 8px" class="b2"><span>12</span><span class="center">88****31 (Me)</span><span class="center">412.37</span><span class="center semi cb">80</span></div>`:me?`<div class="row g32" style="background:#cfe0ff;border-radius:8px;padding:14px 24px"><b class="b2">Me</b><span class="b2">${me}</span></div>`:'';
 const rows=[['4','22****32','1,377.10'],['5','33****31','1,120.40'],['6','44****31','980.12'],['7','55****31','842.66'],['8','66****31','790.03'],['9','10****31','655.71'],['10','88****31','601.14']];
 const gt=mo?'48px 1fr 1fr 60px':'120px 1fr 240px 200px';
 const table=`<div class="col g8"><div style="display:grid;grid-template-columns:${gt};padding:0 8px" class="b2 c2"><span>Rank</span><span class="center">Trader</span><span class="center">Total Cashback (USDT)</span><span class="center">Ranking Reward (USDT)</span></div>${rows.map(r=>`<div style="display:grid;grid-template-columns:${gt};background:#fff;border-radius:8px;padding:14px 8px" class="b2"><span style="padding-left:8px">${r[0]}</span><span class="center">${r[1]}</span><span class="center">${r[2]}</span><span class="center semi cb">200</span></div>`).join('')}</div>`;
 const pager=`<div class="row center b2 c2" style="gap:16px" style="margin-top:8px">⏮ ‹ <span style="width:32px;height:32px;border-radius:50%;background:rgba(0,0,0,.08);display:inline-flex;align-items:center;justify-content:center;color:var(--text-primary)">1</span> 2 3 4 5 6 7 › ⏭</div>`;
 return `<div class="col g16">${title}${pool}<div class="col g16" style="margin-top:24px">${podium}${meRow}${table}${pager}</div></div>`}
function mbNotes(){const txt="Only wallets of the board's exchange registered on TetherMax within 30 days before the participation start date can participate in MAX BOARD.|A wallet that has participated in the same MAX BOARD cannot participate again.|Each MAX BOARD allows one wallet to receive event rewards, and it cannot be changed once set.|If your participating wallet can no longer participate during the participation period, for example because its ownership is transferred to another account, your progress on that MAX BOARD will start over.|Only cashback from trading counts toward the Bingo Gauge. Event rewards are not included.|Cashback is updated once a day, and the update time may vary depending on the exchange. Cashback updated on the last day of the participation period is included.|Checked cells cannot be canceled or moved to another cell.|Event rewards are paid in USDT to your participating wallet after the payout period starts. If ownership of the participating wallet is transferred to another account before payout, the event rewards will be forfeited.|If fraudulent participation is detected, you may be excluded from event rewards without notice.|Event rewards are not paid to users who have deleted their account.|All dates and times are based on UTC.|This event may be changed or terminated without prior notice due to the circumstances of the Company or its affiliates.";
 return `<section style="background:#e9f0ff;padding:${MO()?'40px 0':'80px 0'}">${wrap(`<hr class="divider"><div style="padding:40px 0"><div class="b1 semi" style="margin-bottom:16px">Notes</div><div class="b2 c2" style="line-height:1.7">${txt.split('|').join('<br>')}</div></div><hr class="divider"><div class="row between" style="padding-top:40px"><img src="${A('logo.svg')}" style="width:142px" alt=""><span class="b1 c2">© 2026 TetherMax. All rights reserved.</span></div>`)}${C.note('유의사항 마지막 줄 <code>All dates and times are based on UTC.</code>는 사용자 화면 로컬 표기 원칙(REQ-639)과 충돌 — 질문 목록 ref/질문_rewards.md')}</section>`}

