// 티켓형 행(혜택 Ongoing 목록 [MAX-468] 10954:228240 · 쿠폰 목록 [MAX-499] · MAXOP-796 Completed 행 25847:1339756)
// 왼쪽 77px(모바일 69px) · 점선 구분 · 위아래 반원 홈(x=99 / 모바일 92) · 오른쪽 70px 버튼 또는 상태 칩
function ticket(o){const mo=MO();const lw=mo?69:77,nx=(mo?92:99);
 const dim=o.dim?'color:rgba(0,0,0,.38);':'';
 const left=o.label?`<span style="font-size:10px;font-weight:700;line-height:1.6;letter-spacing:.15px;color:${o.dim?'rgba(0,0,0,.38)':'var(--blue)'};text-align:center">${o.label}</span>`
  :`<div class="col center" style="gap:0;align-items:center;${o.dim?'color:rgba(0,0,0,.38)':'color:var(--blue)'};letter-spacing:.15px"><b style="font-size:20px;line-height:1.6;font-weight:700">${o.n}</b><span style="font-size:10px;line-height:10px">${o.unit||'USDT'}</span></div>`;
 const mid=o.coupon?`<div class="col" style="gap:4px;min-width:0;${dim}"><span style="font-size:12px;line-height:1.4;font-weight:500">${o.cat}</span><span style="font-size:10px;line-height:10px;letter-spacing:.15px;${o.dim?'':'color:rgba(0,0,0,.38)'}">${o.desc}</span></div>`
  :`<div class="col" style="gap:4px;min-width:0"><span style="font-size:10px;line-height:10px;letter-spacing:.15px;color:var(--text-secondary)">${o.cat}</span><span style="font-size:12px;line-height:1.4;font-weight:500;${mo?'':'white-space:nowrap'}">${o.desc}</span></div>`;
 const right=o.chip||(o.btn?`<button class="btn contained primary" style="width:70px;padding:4px 10px;font-size:13px;line-height:1.5;letter-spacing:-.13px;flex:none" ${o.dis?'disabled':''} ${o.go?`data-go="${o.go}"`:''}>${o.btn}</button>`:'');
 const hole=t=>`<span style="position:absolute;left:${nx}px;${t}:-6px;width:12px;height:12px;border-radius:50%;background:var(--bg-accent)"></span>`;
 return `<div style="position:relative;background:#fff;border-radius:4px;filter:drop-shadow(0 1px 2px rgba(0,0,0,.05));height:80px;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:16px;overflow:hidden">${hole('top')}${hole('bottom')}
  <div class="row" style="gap:12px;height:100%;min-width:0;flex:1"><div class="col center" style="width:${lw}px;flex:none;align-items:center;gap:0">${left}</div><span style="align-self:stretch;border-left:1px dashed rgba(0,0,0,.12)"></span>${mid}</div>${right}</div>`}
// 모바일 상단(뒤로 + 오른쪽 아이콘) — 혜택 상세·챌린지·쿠폰 mWeb(10739:232621 · 11982:387214)
const moHead=(back,o={})=>`<div class="row between" style="padding:16px 16px 0;${o.dark?'':'background:var(--bg-accent)'}"><button class="icon-btn" data-go="${back}"><img src="${A(o.dark?'rw-ic-back-w.svg':'rw-ic-back-k.svg')}" class="ic" alt=""></button>${o.title?`<span style="flex:1;font-size:20px;font-weight:500;line-height:1.6;letter-spacing:.15px;margin-left:8px;color:${o.dark?'#fff':'inherit'}">${o.title}</span>`:''}${o.coupon?`<button class="icon-btn" data-go="coupon.box"><img src="${A(o.dark?'rw-ic-coupon-w.svg':'rw-ic-coupon-k.svg')}" class="ic" alt=""></button>`:'<span style="width:40px"></span>'}</div>`;
// 모바일 약관 아코디언(접힘) — 챌린지 mWeb eventRules(10739:223716)
const moTerms=()=>`<div style="background:#fff;border-radius:8px;padding:16px;display:flex;align-items:center;justify-content:space-between"><span class="b1 semi">Terms &amp; Conditions</span><span style="padding:5px;display:inline-flex"><img src="${A('rw-ic-expand.svg')}" style="width:20px;height:20px" alt=""></span></div>`;
// 빈 상태 — 혜택 Completed(10954:230325 · 11100:221304) · 쿠폰 No coupons(11982:388195) 같은 틀
const emptyBox=(msg,btn,go,h)=>`<div class="col center" style="align-items:center;justify-content:center;gap:8px;min-height:${h||(MO()?240:380)}px;text-align:center"><span style="font-size:12px;line-height:1.66;letter-spacing:.4px;color:var(--text-secondary)">${msg}</span>${btn?`<button class="btn outlined black" style="padding:4px 10px;font-size:13px;line-height:1.5" data-go="${go||''}">${btn}</button>`:''}</div>`;

