// 계정 선택 행 (쿠폰 · 리그 · 챌린지 공통) — DEX 「쿠폰 · 사용할 계정 선택」(29062:117713 · 117894) 행 모양
// 비활성 계정은 기존 [MAX-499] 「Deactivated UIDs」(12474:164724)대로 흐리게만(배지 없음)
// =====================================================================
function acctRow(a,o={}){const on=o.sel===a.id,dis=a.deact;
 const label=a.dex?`<div class="col" style="gap:0;min-width:0"><span class="b2">${a.name} · ${T('Wallet','지갑')}</span><span class="b2 addr" style="font-family:inherit">${a.addr}</span></div>`:`<span class="b1">UID ${a.uid}</span>`;
 return `<div class="row g12" style="border:1px solid ${on?'var(--blue)':'var(--divider)'};border-radius:12px;padding:12px;min-height:60px;${dis?'opacity:.38;cursor:not-allowed':'cursor:pointer'}">${logo(a.name,36)}<div class="grow">${label}</div></div>`}
const ACC={bybit:{id:'bybit',name:'Bybit',uid:'123456789'},bitget:{id:'bitget',name:'Bitget',uid:'936582739'},edgex:{id:'edgex',name:'EdgeX',dex:1,addr:W.edgex},
 okx:{id:'okx',name:'OKX',uid:'****4321'},bybitD:{id:'bybitD',name:'Bybit',uid:'****1122',deact:1},aster:{id:'aster',name:'Aster',dex:1,addr:W.v22aster},apex:{id:'apex',name:'ApeX',dex:1,addr:W.v22apex},edge22:{id:'edge22',name:'EdgeX',dex:1,addr:W.v22edge}};
function acctList(cex,dex,sel){return `${cex.length?`<div class="b2 semi" style="color:#3c4a5c">${T('Centralised Exchanges','중앙화 거래소')}</div>${cex.map(a=>acctRow(a,{sel})).join('')}`:''}${dex.length?`<div class="b2 semi" style="color:#3c4a5c;margin-top:4px">${T('Decentralised Exchanges','탈중앙화 거래소')}</div>${dex.map(a=>acctRow(a,{sel})).join('')}`:''}`}
// 모바일도 가운데 다이얼로그(DEX 29062:117894 · 기존 11982:373721) — 바텀시트 아님
function pickDialog(title,sub,list,o={}){const mo=MO();
 return `<div style="background:#fff;border-radius:4px;box-shadow:var(--elev24);width:${mo?'343px':(o.w||480)+'px'};max-width:100%;padding:${mo?20:24}px;display:flex;flex-direction:column;gap:8px;max-height:${mo?'640px':'none'};overflow:auto"><div style="font-size:${mo?20:24}px;font-weight:600;line-height:${mo?1.6:1.334};${o.center?'text-align:center':''}">${title}</div>${sub?`<div class="${mo?'b2':'b1'} c2" style="${o.center?'text-align:center':''}">${sub}</div>`:''}<div class="col g8" style="margin-top:16px">${list}</div><div class="row g8" style="margin-top:16px">${greyBtn(T('Cancel','취소'),o.cancel||'')}${C.btn(T('Confirm','확인'),{full:true,disabled:!!o.disabled,go:o.ok||''})}</div></div>`}

