function evCard(o){return `<div style="background:#fff;border-radius:8px;box-shadow:0 4px 5px rgba(0,0,0,.1);padding:16px" class="col g16"><div style="position:relative;height:140px;border-radius:4px;overflow:hidden;background:${o.img?'#000':'#1f2a3c'}">${o.img?`<img src="${A(o.img)}" style="width:100%;height:100%;object-fit:cover" alt="">`:''}<div style="position:absolute;left:0;top:0;width:180px;height:140px;padding:24px 16px 16px;color:${o.img?'#fff':'#26364d'};font-weight:600;font-size:16px;line-height:1.5">${o.title}</div><span class="row" style="position:absolute;left:0;top:0;background:#1c1c1e;border-radius:4px 0 4px 0;padding:4px 8px;gap:4px;color:#fff;font-size:11px">${logo(o.ex,14)}${o.ex}</span></div><div class="row between b2"><span class="row g4 c2"><img src="${A('rw-ic-reward.svg')}" style="width:16px" alt="">Rewards</span><span>${o.reward}</span></div><div class="row g8"><img src="${A('rw-ic-clock.svg')}" style="width:16px" alt=""><span class="row g4" style="font-size:12px">${[['121','D'],['02','H'],['00','M'],['30','S']].map(([n,u])=>`<span style="background:rgba(207,216,220,.3);border-radius:4px;padding:4px;font-weight:500">${n}</span><span class="c2">${u}</span>`).join('')}</span></div>${C.btn('Join Now',{size:'md',full:true})}</div>`}
const EV_SEL=['Bitget','EdgeX'];   // Figma 표본: 2곳 선택 → 셀렉트 `Bitget+1`
const evLabel=sel=>sel.length?sel[0]+(sel.length>1?'+'+(sel.length-1):''):'All Exchanges';
function evFilterList(sel=EV_SEL){const row=(n,on,isLogo=true)=>`<div class="row between" data-ev-check="${n}" role="checkbox" aria-checked="${!!on}" tabindex="0" style="height:54px;cursor:pointer"><span class="row g8 b1">${isLogo?logo(n,20):''}${n}</span><span class="chk${on?' on':''}"><i></i></span></div>`;
 const cex=['Bitget','Bybit','Binance','OKX'],dex=['EdgeX'],all=cex.concat(dex);
 return `<div data-ev-filter><div class="row g8" data-ev-chips style="padding:8px 0 4px">${['All','CEX','DEX'].map(k=>C.chip(k,k==='All').replace('<span class="chip',`<span data-ev-chip="${k}" role="button" tabindex="0" class="chip`)).join('')}</div>${row('All Exchanges',sel.length===all.length,false)}<div data-ev-grp="CEX"><div class="b2 semi" style="color:#3c4a5c;padding:4px 0">${T('Centralised Exchanges','중앙화 거래소')}</div>${cex.map(n=>row(n,sel.includes(n))).join('')}</div><div data-ev-grp="DEX"><div class="b2 semi" style="color:#3c4a5c;padding:4px 0">${T('Decentralised Exchanges','탈중앙화 거래소')}</div>${dex.map(n=>row(n,sel.includes(n))).join('')}</div></div>`}
function evPage(o={}){const mo=MO();
 const sel=`<div style="position:relative"><div class="row between" style="width:${mo?'100%':'280px'};height:36px;border:1px solid var(--input-border);border-radius:4px;padding:0 8px 0 12px;background:#fff;cursor:pointer" data-go="events.list:${mo?'filterMo':'filterPc'}"><span class="b2" data-ev-label>${o.selLabel||'All Exchanges'}</span>${ic('arrow-drop-down')}</div>${o.dropdown?`<div style="position:absolute;right:0;top:40px;width:335px;background:#fff;border-radius:8px;box-shadow:var(--elev8);padding:8px 20px;z-index:5">${evFilterList()}</div>`:''}</div>`;
 const cards=[{ex:'EdgeX',title:'EdgeX trading event',reward:'5.00 USDT'},{ex:'MEXC',img:'rw-ev-mexc.jpg',title:'Gold, Silver, Oil &amp; Stock Futures Zero Fees',reward:'0-Fee Mega Cash Reward'},{ex:'Kucoin',img:'rw-ev-kucoin.jpg',title:'Trade to earn $500,000 prize pool',reward:'$500,000.00'},{ex:'Kucoin',img:'rw-ev-kucoin.jpg',title:'Trade to earn $500,000 prize pool',reward:'$500,000.00'}];
 return wrap(`<div class="col" style="gap:${mo?24:40}px;padding:${mo?'16px 0 48px':'40px 0 80px'}"><div class="col g16"><div style="position:relative;height:${mo?220:350}px;border-radius:8px;overflow:hidden;background:#000"><img src="${A('rw-ev-banner.jpg')}" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:right" alt=""><div class="col" style="position:relative;justify-content:center;height:100%;padding:${mo?'0 16px':'0 48px'};gap:24px"><span class="row" style="align-self:flex-start;background:rgba(255,255,255,.1);border-radius:16px;padding:4px 8px;gap:4px;color:#fff;font-size:13px"><span style="width:20px;height:20px;border-radius:50%;background:#000;color:#fff;font-size:11px;display:inline-flex;align-items:center;justify-content:center;font-weight:700">B</span>BioFin</span><div><div class="h5" style="color:#fff;font-weight:700">BioFin Cashback Boost</div><div class="h6" style="color:rgba(255,255,255,.8);font-weight:400">Up to 85% cashback</div></div>${`<button class="btn contained primary lg" style="align-self:flex-start">Join Now</button>`}</div></div><div class="row center g4"><span style="width:24px;height:6px;border-radius:3px;background:var(--blue)"></span><span style="width:6px;height:6px;border-radius:3px;background:var(--divider)"></span><span style="width:6px;height:6px;border-radius:3px;background:var(--divider)"></span></div></div>
 <div class="col g24"><div class="row between wrap" style="gap:12px">${tabBar([['s','Special Events'],['x','Exclusive'],['e','Exchange Events']],'e',{style:'border-bottom:0'})}${sel}</div><div style="display:grid;grid-template-columns:${mo?'1fr':'repeat(3,minmax(0,1fr))'};gap:24px">${cards.map(evCard).join('')}</div></div></div>`,1056)}
R.screen({id:'events.list',group:'rewards',title:'이벤트',route:'/events',fu:['FU-072'],shell:{nav:'rewards',moTitle:['Events','이벤트'],moNav:'events'},
 states:[
  {id:'exchange',label:'거래소 이벤트 탭',figma:{pc:'29062:112586',mo:'29062:112729'},note:'V2.2에 별도 화면 없음(FU-072) — Figma대로. 거래소 이벤트 탭에 DEX 이벤트 노출(REQ-437)'},
  {id:'filterPc',label:'거래소 필터 (PC 셀렉트·목록)',figma:{pc:'29069:6595'},note:'칩 All · CEX · DEX(CEX = 중앙화 그룹만 · DEX = 탈중앙화 그룹만) → All Exchanges → 그룹. 여러 개 선택 시 셀렉트 <code>{첫 거래소}+{n}</code>. 그룹 드롭다운 + 범위 선택, 배지 없음, 이벤트가 등록된 거래소만(REQ-437). 셀렉트 29069:6626'},
  {id:'filterMo',label:'거래소 필터 (모바일 시트)',figma:{mo:'29069:6544'},note:'모바일 바텀시트 <code>Select Exchanges</code> · <code>Apply (n)</code>'},
 ],
 render(st){
  if(st==='filterPc')return evPage({dropdown:!MO(),selLabel:evLabel(EV_SEL)})+(MO()?C.note('PC 전용 프레임 — 모바일은 <code>filterMo</code>'):'');
  if(st==='filterMo'){const sheet=`<div style="background:#fff;border-radius:16px 16px 0 0;width:100%;${MO()?'':'max-width:375px'};padding:8px 20px 16px;align-self:flex-end"><div class="sheet-grab" style="margin:0 auto 16px"></div><div class="b1 semi center" style="margin-bottom:12px">Select Exchanges</div>${evFilterList()}<div class="row g8" style="margin-top:16px">${greyBtn('Close','events.list:exchange')}${C.btn(`Apply (${EV_SEL.length})`,{full:true,go:'events.list:exchange'}).replace('<button ','<button data-ev-apply ')}</div></div>`;
   return ovSelf('events.list','exchange',sheet,false)+(MO()?'':C.note('모바일 전용 프레임 — PC는 <code>filterPc</code>'))}
  return evPage()+C.note('Figma 탭은 <code>Special Events</code> · <code>Exclusive</code> · <code>Exchange Events</code> 3개. 정책 REQ-437은 <code>테더맥스 전용 이벤트</code> · <code>거래소 이벤트</code> 두 탭 기준 — 질문 목록 참고. EdgeX 카드 이미지는 Figma에서도 자리표시(어두운 배경 + 제목)');
 }});

